export interface VeedCleanAudioInput {
    /**
     * Audio
     * @description The recording to clean. Any audio or video ffmpeg can decode (wav, mp3, m4a, aac, ogg, mp4, mov, webm, ...); a video's audio track is used (call /video to get the video back with the cleaned track) and multi-channel input is mixed down to mono. Up to 30 minutes and 512 MB. A public URL or a data URI.
     * @example https://v3b.fal.media/files/b/0aaaa91c/5KspxZ3psz3KmDvSeYVk__noisy_example.m4a
     */
    audio_url: string;
    /**
     * Output format
     * @description Container for the 48 kHz mono 16-bit output. FLAC is lossless at about half the size of WAV.
     * @default flac
     * @enum {string}
     */
    output_format?: 'flac' | 'wav';
    /**
     * Strength
     * @description How much of the original is allowed to remain under speech: the suppression floor is 1 - strength (the default 0.874 is the validated -18 dB). Lower keeps more room tone behind the voice; silence between words is always fully cleaned.
     * @default 0.874
     */
    strength?: number;
    /**
     * Target loudness (LUFS)
     * @description Integrated loudness of the output (ITU-R BS.1770). The default -19 LUFS is the level the VEED editor delivers; true peak is capped at -1.1 dBTP. Pass null through the API to skip loudness normalization and keep the input level.
     * @default -19
     */
    target_lufs?: number;
}

export interface VeedCleanAudioOutput {
    /**
     * Cleaned audio
     * @description The denoised recording: 48 kHz mono 16-bit, same duration as the input, loudness-normalized.
     * @example {
     *       "url": "https://v3b.fal.media/files/b/0aaaa933/tYOEy9H8r67qdQEC33yMe_denoised.flac",
     *       "content_type": "audio/flac",
     *       "file_name": "denoised.flac"
     *     }
     */
    audio: Components.File;
    /**
     * Audio duration
     * @description Input duration in seconds. Billing: whole seconds rounded up to full minutes, minimum 1 unit.
     */
    audio_duration: number;
}

