export interface SmartResizeInput {
    /**
     * Image URL
     * @description The URL of the source image to resize.
     * @example https://storage.googleapis.com/falserverless/example_inputs/nano-banana-edit-input.png
     */
    image_url: string;
    /**
     * Num Images Per Size
     * @description The number of nano-banana-pro variants to produce for each target size. The response images list will contain ``len(target_sizes) * num_images_per_size`` images in total.
     * @default 1
     */
    num_images_per_size?: number;
    /**
     * Output Format
     * @description The output image format.
     * @default png
     * @enum {string}
     */
    output_format?: 'jpeg' | 'png' | 'webp';
    /**
     * Prompt
     * @description Optional extra instruction that is forwarded to nano-banana-pro alongside the auto-generated resize prompt. Leave empty to let the model preserve the original image content as closely as possible.
     * @default
     * @example
     */
    prompt?: string;
    /**
     * Resolution
     * @description Hint for the minimum resolution tier to use internally. The smart-resize algorithm may pick a higher tier automatically when the requested target size is too large for this tier. This field does not affect the final output dimensions — those come from ``target_sizes``.
     * @default 1K
     * @enum {string}
     */
    resolution?: '1K' | '2K' | '4K';
    /**
     * Safety Tolerance
     * @description The safety tolerance level applied to the inner nano-banana-pro /edit calls. Higher numbers loosen safety filtering.
     * @default 4
     * @enum {string}
     */
    safety_tolerance?: '1' | '2' | '3' | '4' | '5' | '6';
    /**
     * Seed
     * @description Optional random seed forwarded to the inner nano-banana-pro /edit calls for reproducibility. The same seed is used for every target size when set.
     */
    seed?: number;
    /**
     * Sync Mode
     * @description When True, the response contains data URIs in place of CDN URLs so the client can decode the images without an extra HTTP request. Adds latency for large outputs.
     * @default false
     */
    sync_mode?: boolean;
    /**
     * Target Sizes
     * @description The list of target dimensions to generate, each written as ``<width>x<height>`` (e.g. ``"1920x1080"``). One output image is produced per target size (multiplied by ``num_images_per_size``). The endpoint internally picks the smallest nano-banana-pro preset that fully covers each target so the final image is a pixel-perfect match with no upscaling.
     * @example [
     *       "1024x1024",
     *       "1920x1080",
     *       "768x1344"
     *     ]
     */
    target_sizes: string[];
}

export interface SmartResizeOutput {
    /**
     * Description
     * @description The description of the generated images.
     */
    description: string;
    /**
     * Images
     * @description All generated images, flattened across every target size. Order matches the order of ``results`` below: the first ``num_images_per_size`` entries correspond to ``target_sizes[0]`` and so on.
     * @example [
     *       {
     *         "url": "https://storage.googleapis.com/falserverless/example_outputs/nano-banana-pro-edit-output.png",
     *         "file_name": "nano-banana-pro-edit-output.png",
     *         "content_type": "image/png"
     *       }
     *     ]
     */
    images: Components.ImageFile[];
    /**
     * Results
     * @description Per-target-size breakdown with the requested width/height and the nano-banana-pro (aspect_ratio, resolution) preset that was used internally.
     */
    results: Components.SmartResizeResult[];
}

