export interface PatinaMaterialExtractInput {
    /**
     * Enable Prompt Expansion
     * @description Expand prompt with an LLM for richer detail. Adds ~0.0025 credits.
     * @default true
     */
    enable_prompt_expansion?: boolean;
    /**
     * Enable Safety Checker
     * @description Enable the safety checker for generated images.
     * @default true
     */
    enable_safety_checker?: boolean;
    /**
     * Image Size
     * @description Output texture dimensions in pixels.
     * @default square_hd
     */
    image_size?:
        | Components.ImageSize
        | (
              | 'square_hd'
              | 'square'
              | 'portrait_4_3'
              | 'portrait_16_9'
              | 'landscape_4_3'
              | 'landscape_16_9'
          );
    /**
     * Image URL
     * @description URL of the image to extract a texture from.
     * @example https://v3b.fal.media/files/b/0a95600b/IVhCXWN-sE1xj1SpYAGpL_31b6f371-90ae-4835-851e-23cd809cfb86.png
     */
    image_url: string;
    /**
     * Maps
     * @description Which PBR maps to predict. Deselect all to skip PBR estimation entirely. Defaults to all five.
     * @default [
     *       "basecolor",
     *       "normal",
     *       "roughness",
     *       "metalness",
     *       "height"
     *     ]
     */
    maps?: ('basecolor' | 'normal' | 'roughness' | 'metalness' | 'height')[];
    /**
     * Number of Images
     * @description Number of texture images to generate.
     * @default 1
     */
    num_images?: number;
    /**
     * Number of Inference Steps
     * @description Number of denoising steps for texture generation.
     * @default 8
     */
    num_inference_steps?: number;
    /**
     * Output Format
     * @description Output image format for textures and PBR maps.
     * @default png
     * @enum {string}
     */
    output_format?: 'jpeg' | 'png' | 'webp';
    /**
     * Prompt
     * @description Describe which texture to extract from the image.
     * @example the wall
     */
    prompt: string;
    /**
     * Seed
     * @description Random seed for reproducible generation.
     */
    seed?: number;
    /**
     * Strength
     * @description How much to transform the input image. Only used when image_url is provided.
     * @default 0.6
     */
    strength?: number;
    /**
     * Tile Size
     * @description Tile size in latent space. Automatically capped to the generated image dimensions on tiled axes (64 = 512px, 128 = 1024px).
     * @default 128
     */
    tile_size?: number;
    /**
     * Tile Stride
     * @description Tile stride in latent space. Automatically capped to half the effective tile size.
     * @default 64
     */
    tile_stride?: number;
    /**
     * Tiling Mode
     * @description Tiling direction: 'both' (omnidirectional), 'horizontal', or 'vertical'.
     * @default both
     * @enum {string}
     */
    tiling_mode?: 'both' | 'horizontal' | 'vertical';
    /**
     * Upscale Factor
     * @description Upscale factor for predicted PBR maps via SeedVR seamless upscaling. 0 = no upscaling, 2 = 2× resolution, 4 = 4× resolution. The base texture image is not upscaled.
     * @default 0
     * @enum {integer}
     */
    upscale_factor?: 0 | 2 | 4;
}

