export interface MossImageInput {
    /**
     * Enable Prompt Expansion
     * @description Plan a structured layout from your prompt before generation. Preserves requested visible text and uses the selected image dimensions. If enhancement is unavailable, uses the original prompt.
     * @default true
     */
    enable_prompt_expansion?: boolean;
    /**
     * Enable Safety Checker
     * @description Enable output content moderation. Disabling it requires account authorization; unauthorized requests are always checked, and images flagged as unsafe are returned as black images.
     * @default true
     */
    enable_safety_checker?: boolean;
    /**
     * Guidance Scale
     * @description Classifier-free guidance scale.
     * @default 3
     */
    guidance_scale?: number;
    /**
     * Image Size
     * @description Output image size. Width and height are rounded to multiples of 16 between 512 and 2048 pixels.
     * @default square_hd
     */
    image_size?:
        | Components.ImageSize
        | (
              | 'square_hd'
              | 'square'
              | 'portrait_4_3'
              | 'portrait_16_9'
              | 'landscape_4_3'
              | 'landscape_16_9'
          );
    /**
     * Negative Prompt
     * @description Negative prompt. When empty, guidance uses transformer layer skipping for the negative branch.
     * @default
     */
    negative_prompt?: string;
    /**
     * Number of Images
     * @description Number of images to generate.
     * @default 1
     */
    num_images?: number;
    /**
     * Number of Inference Steps
     * @description Number of denoising steps.
     * @default 50
     */
    num_inference_steps?: number;
    /**
     * Output Format
     * @description Output image format.
     * @default jpeg
     * @enum {string}
     */
    output_format?: 'jpeg' | 'png' | 'webp';
    /**
     * Prompt
     * @description Text prompt for image generation. Supports natural language, tag sequences, and JSON layouts.
     * @example A wide view of a refrigerator beside a kitchen counter with a fruit bowl. A small sticky note on the refrigerator door is handwritten in Chinese:
     *     "记得买牛奶和鸡蛋！
     *     牛奶两盒，鸡蛋一打。"
     */
    prompt: string;
    /**
     * Seed
     * @description Random seed for reproducible generation.
     */
    seed?: number;
    /**
     * Sync Mode
     * @description Return images as data URIs instead of storing them in request history.
     * @default false
     */
    sync_mode?: boolean;
}

